/**
 * How a maintainer resolves the reports of a recommendation ([ResolveRequest].Resolution): the values of
 * reports.resolution (store.Resolutions).
 */
export const ResolutionKeptHidden = "kept_hidden";
/**
 * How a maintainer resolves the reports of a recommendation ([ResolveRequest].Resolution): the values of
 * reports.resolution (store.Resolutions).
 */
